    horzEdge.Top = pt;
    wasTrimmed = true;
    if (IsMaxima(horzEdge)) break;
    pt = NextVertex(horzEdge).Pt;
  }
  if (wasTrimmed) SetDx(horzEdge); // +/-infinity
}
