fn rint(x: f64) -> f64 {
    // round half to even
    let r = x.round(); // half away from zero
    if (r - x).abs() == 0.5 {
        // r is x±0.5; choose even
        let fl = x.floor();
        if (fl as i64) % 2 == 0 { fl } else { fl + 1.0 } // careful sign
    } else { r }
}
```

Simpler: `x.round_ties_even` equivalent: 

```rust
fn round_ties_even(x: f64) -> f64 {
    let t = x.fract();
    if t.abs() != 0.5 { x.round() } else { x.trunc() + if (x.trunc() as i64) % 2 == 0 { 0.0 } else { x.signum() } }
}
```

