```cpp
inline PointD GetUnitNormal(const Point64& pt1, const Point64& pt2)
{
  double dx = (double)(pt2.x - pt1.x);
  double dy = (double)(pt2.y - pt1.y);
  if ((dx == 0) && (dy == 0)) return PointD();

  double f = 1.0 / std::hypot(dx, dy);
  dx *= f;
  dy *= f;
  return PointD(dy, -dx);
}
