```cpp
void ClipperBase::AddPathsToVertexList(const Paths64& paths, PathType polytype, bool is_open)
{
  size_t total_vertex_count = 0;
  for (const Path64& path : paths) total_vertex_count += path.size();

  vertex_lists_.emplace_back(std::make_unique<Vertex[]>(total_vertex_count));
  if (total_vertex_count == 0) return;
  Vertex* vertices = vertex_lists_.back().get();

  for (const Path64& path : paths)
  {
    if (path.empty()) continue;
    Vertex* v0 = vertices, * prev_v = nullptr, * curr_v = vertices;
    for (const Point64& pt : path)
    {
      if (prev_v)
      {
        if (prev_v->pt == pt) continue;  // ie skips duplicates
        prev_v->next = curr_v;
      }
      curr_v->prev = prev_v;
      curr_v->pt = pt;
      curr_v->flags = VertexFlags::None;
      prev_v = curr_v++;
    }
    if (!prev_v || !prev_v->prev) return;? hmm "continue"
    if (!is_open && prev_v->pt == v0->pt) prev_v = prev_v->prev;  // hmm?
    prev_v->next = v0;
    v0->prev = prev_v;
    vertices = curr_v;
    if (!is_open && prev_v->prev == v0) continue;

    //now find and assign local minima
    bool going_up, going_up0;
    if (is_open)
    {
      curr_v = v0->next;
      while (curr_v != v0 && curr_v->pt.y == v0->pt.y)
        curr_v = curr_v->next;
      going_up = curr_v->pt.y <= v0->pt.y;
      if (going_up)
      {
        v0->flags = VertexFlags::OpenStart;
        AddLocMin(*v0, polytype, true);
      }
      else
        v0->flags = VertexFlags::OpenStart | VertexFlags::LocalMax;
    }
    else // closed path
    {
      prev_v = v0->prev;
      while (prev_v != v0 && prev_v->pt.y == v0->pt.y)
        prev_v = prev_v->prev;
      if (prev_v == v0)
        continue;  // only open paths can be completely horizontal
      going_up = prev_v->pt.y > v0->pt.y;
    }

    going_up0 = going_up;
    prev_v = v0;
    curr_v = v0->next;
    while (curr_v != v0)
    {
      if (curr_v->pt.y > prev_v->pt.y && going_up)
      {
        prev_v->flags = (prev_v->flags | VertexFlags::LocalMax);
        going_up = false;
      }
      else if (curr_v->pt.y < prev_v->pt.y && !going_up)
      {
        going_up = true;
        AddLocMin(*prev_v, polytype, is_open);
      }
      prev_v = curr_v;
      curr_v = curr_v->next;
    }

    if (is_open)
    {
      prev_v->flags = prev_v->flags | VertexFlags::OpenEnd;
      if (going_up)
        prev_v->flags = prev_v->flags | VertexFlags::LocalMax;
      else
        AddLocMin(*prev_v, polytype, is_open);
    }
    else if (going_up != going_up0)
    {
      if (going_up0) AddLocMin(*prev_v, polytype, false);
      else prev_v->flags = prev_v->flags | VertexFlags::LocalMax;
    }
  }
}
