private static void SwapOutRecs(Active e1, Active e2)
{
  OutRec? or1 = e1.OutRec;
  OutRec? or2 = e2.OutRec;
  if (or1 == or2)
  {
    Active? e = or1!.FrontEdge;
    or1.FrontEdge = or1.BackEdge;
    or1.BackEdge = e;
    return;
  }
  if (or1 != null)
  {
    if (e1 == or1.FrontEdge)
      or1.FrontEdge = e2;
    else
      or1.BackEdge = e2;
    e2.OutRec = or1;
  }
  if (or2 != null)
  {
    if (e2 == or2.FrontEdge)
      or2.FrontEdge = e1;
    else
      or2.BackEdge = e1;
    e1.OutRec = or2;
  }
}
