IsValidAelOrder(resident, newcomer): checks newcomer.curr_x >= resident.curr_x, with tie-break via cross products:

```cpp
bool IsValidAelOrder(const Active& resident, const Active& newcomer)
{
  if (newcomer.curr_x != resident.curr_x)
    return newcomer.curr_x > resident.curr_x;

  //get the turning direction: a1, a2, a3
  double d = CrossProduct(resident.top, newcomer.bot, newcomer.top);
  if (d != 0) return d < 0;

  //edges must be collinear to get here
  //for starting open paths, place them according to
  //the direction they're about to turn
  if (!IsMaxima(resident) && resident.top.y > newcomer.top.y)
  {
    return CrossProduct(newcomer.bot, resident.top, NextVertex(resident)->pt) <= 0;
  }
  else if (!IsMaxima(newcomer) && newcomer.top.y > resident.top.y)
  {
    return CrossProduct(newcomer.bot, newcomer.top, NextVertex(newcomer)->pt) >= 0;
  }
  else
  {
    int64_t y = newcomer.bot.y;
    bool newcomerIsLeft = newcomer.is_left;

    if (resident.bot.y != y || resident.local_min->vertex->pt.y != y)
      newcomer.is_left = newcomerIsLeft;
    else if (resident.is_left != newcomerIsLeft)
      newcomer.is_left = !newcomerIsLeft;
    else if (CrossProduct(PrevPrevVertex(resident)->pt, resident.bot, resident.top) > 0)
      newcomer.is_left = newcomerIsLeft;
    else
      newcomer.is_left = !newcomerIsLeft;
  }
  return newcomer.is_left;
}
```

