pub fn format_g6(v: f64) -> String {
    if v == 0.0 { return if v.is_sign_negative() { "-0".into() } else { "0".into() } }
    // 6 significant digits
    let s = format!("{:.5e}", v); // e.g. "1.48927e4", "-1.48927e4", "1.00000e-5"
    // parse
    let (mant, exp) = s.split_once('e').unwrap();
    let exp: i32 = exp.parse().unwrap();
    let neg = mant.starts_with('-');
    let digits: String = mant.chars().filter(|c| c.is_ascii_digit()).collect();
    // digits has 6 digits
    if exp >= 6 || exp < -4 {
        // scientific: d.ddddde±XX, strip trailing zeros in fraction
        let mut frac = digits[1..].trim_end_matches('0').to_string();
        let m = if frac.is_empty() { digits[..1].to_string() } else { format!("{}.{}", &digits[..1], frac) };
        format!("{}{}e{}{:02}", if neg {"-"} else {""}, m, if exp < 0 {"-"} else {"+"}, exp.abs())
    } else {
        // fixed
        let int_part_len = exp + 1;
        let out = if int_part_len >= 6 {
            digits.clone() + &"0".repeat((int_part_len - 6) as usize)
        } else if int_part_len > 0 {
            let ip = &digits[..int_part_len as usize];
            let fp = digits[int_part_len as usize..].trim_end_matches('0');
            if fp.is_empty() { ip.to_string() } else { format!("{}.{}", ip, fp) }
        } else {
            // 0.00ddd
            let fp_full = format!("{}{}", "0".repeat((-int_part_len) as usize), digits);
            let fp = fp_full.trim_end_matches('0');
            format!("0.{}", fp)
        };
        format!("{}{}", if neg {"-"} else {""}, out)
    }
}
