fn parse_stoi(s: &str) -> Result<i32, ()> {
    let b = s.as_bytes();
    let mut i = 0;
    while i < b.len() && (b[i] as char).is_ascii_whitespace() { i += 1; } // C isspace: ' ', \t, \n, \v, \f, \r
    let mut sign: i64 = 1;
    if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
        if b[i] == b'-' { sign = -1; }
        i += 1;
    }
    let start = i;
    let mut val: i64 = 0;
    while i < b.len() && b[i].is_ascii_digit() {
        val = val * 10 + (b[i] - b'0') as i64;
        // stoi throws out_of_range if beyond int range; mimic: if val*sign outside i32 → error
        if val > 0x7FFFFFFF + 1 { return Err(()); } // will refine below
        i += 1;
    }
    if i == start { return Err(()); } // invalid_argument
    let v = sign * val;
    if v < i32::MIN as i64 || v > i32::MAX as i64 { return Err(()); } // out_of_range
    Ok(v as i32)
}
