/// Mimic std::stoi on argv[1]: skip whitespace, optional sign, digits.
/// Returns Err on invalid_argument / out_of_range (C++ would abort).
fn parse_stoi(s: &str) -> Result<i32, ()> {
    let b = s.as_bytes();
    let mut i = 0usize;
    while i < b.len() && matches!(b[i], b' ' | b'\t' | b'\n' | b'\x0b' | b'\x0c' | b'\r') {
        i += 1;
    }
    let mut sign: i64 = 1;
    if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
        if b[i] == b'-' {
            sign = -1;
        }
        i += 1;
    }
    let start = i;
    let mut val: i64 = 0;
    while i < b.len() && b[i].is_ascii_digit() {
        val = val * 10 + (b[i] - b'0') as i64;
        if val > 2_147_483_648 {
            return Err(()); // out_of_range for int
        }
        i += 1;
    }
    if i == start {
        return Err(()); // invalid_argument
    }
    let v = sign * val;
    if v < i32::MIN as i64 || v > i32::MAX as i64 {
        return Err(()); // out_of_range
    }
    Ok(v as i32)
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let complexity: i32 = if args.len() > 1 {
        match parse_stoi(&args[1]) {
            Ok(v) => v.min(5),
            Err(()) => {
                // mimic uncaught exception -> abort, no stdout
                std::process::exit(134);
            }
        }
    } else {
        3
    };

    // ---- build 3 geometry layers ----
    let pi = 3.1415926f64;
    let mut geometry_layers: Vec<Paths64> = Vec::new();

    // layer 1: circles and squares
    let mut layer1: Paths64 = Vec::new();
    for i in 0..complexity as i64 {
        let mut circle: Path64 = Vec::new();
        for j in 0..24i64 {
            let angle = 2.0 * pi * j as f64 / 24.0;
            let x = 100 + i * 80 + (40.0 * angle.cos()) as i64;
            let y = 100 + (40.0 * angle.sin()) as i64;
            circle.push(Point64::new(x, y));
        }
        layer1.push(circle);

        let size: i64 = 50 + i * 10;
        let square: Path64 = vec![
            Point64::new(200 + i * 60, 200),
            Point64::new(200 + i * 60 + size, 200),
            Point64::new(200 + i * 60 + size, 200 + size),
            Point64::new(200 + i * 60, 200 + size),
        ];
        layer1.push(square);
    }
    geometry_layers.push(layer1);

    // layer 2: stars and spirals
    let mut layer2: Paths64 = Vec::new();
    for i in 0..complexity as i64 {
        let mut star: Path64 = Vec::new();
        let points: i64 = 5 + i;
        for j in 0..(points * 2) {
            let angle = 2.0 * pi * j as f64 / (points * 2) as f64;
            let radius = if j % 2 == 0 { 35.0 } else { 20.0 };
            let x = 150 + (radius * angle.cos()) as i64;
            let y = 150 + i * 100 + (radius * angle.sin()) as i64;
            star.push(Point64::new(x, y));
        }
        layer2.push(star);

        let mut spiral: Path64 = Vec::new();
        for j in 0..30i64 {
            let t = j as f64 * 0.3;
            let radius = 10.0 + t * 4.0;
            let angle = t;
            let x = 300 + (radius * angle.cos()) as i64;
            let y = 150 + i * 100 + (radius * angle.sin()) as i64;
            spiral.push(Point64::new(x, y));
        }
        layer2.push(spiral);
    }
    geometry_layers.push(layer2);

    // layer 3: hexagon grid and triangles
    let mut layer3: Paths64 = Vec::new();
    for i in 0..complexity as i64 {
        for j in 0..complexity as i64 {
            let center_x: i64 = 50 + i * 70;
            let center_y: i64 = 300 + j * 70;
            let mut hex: Path64 = Vec::new();
            for k in 0..6i64 {
                let angle = 2.0 * pi * k as f64 / 6.0;
                let x = center_x + (25.0 * angle.cos()) as i64;
                let y = center_y + (25.0 * angle.sin()) as i64;
                hex.push(Point64::new(x, y));
            }
            layer3.push(hex);

            let triangle: Path64 = vec![
                Point64::new(center_x + 100, center_y),
                Point64::new(center_x + 100 + 30, center_y + 50),
                Point64::new(center_x + 100 - 30, center_y + 50),
            ];
            layer3.push(triangle);
        }
    }
    geometry_layers.push(layer3);

    // ---- 20 API operations chain ----
    let mut accumulated: Paths64 = Vec::new();
    for layer in &geometry_layers {
        let union_layer = union_op(layer, FillRule::EvenOdd);
        accumulated.extend(union_layer);
    }

    let all_union = union_op(&accumulated, FillRule::EvenOdd);

    let mut processed: Paths64 = Vec::new();
    for i in 0..geometry_layers.len() {
        let layer_union = union_op(&geometry_layers[i], FillRule::EvenOdd);
        for j in (i + 1)..geometry_layers.len() {
            let other_union = union_op(&geometry_layers[j], FillRule::EvenOdd);
            let inter = intersect(&layer_union, &other_union, FillRule::EvenOdd);
            let diff = difference(&layer_union, &other_union, FillRule::EvenOdd);
            let xorb = xor_op(&layer_union, &other_union, FillRule::EvenOdd);
            processed.extend(inter);
            processed.extend(diff);
            processed.extend(xorb);
        }
    }

    let all_processed = union_op(&processed, FillRule::NonZero);

    let offsets = [2.0f64, -1.5, 3.0, -2.0];
    let join_types = [JoinType::Round, JoinType::Miter, JoinType::Square, JoinType::Bevel];
    let mut offset_results: Paths64 = Vec::new();
    for i in 0..4 {
        let offset = inflate_paths(&all_processed, offsets[i], join_types[i], EndType::Polygon, 2.0, 0.0);
        offset_results.extend(offset);
    }

    let union_offsets = union_op(&offset_results, FillRule::EvenOdd);

    let final_intersect = intersect(&union_offsets, &all_union, FillRule::EvenOdd);
    let final_diff = difference(&union_offsets, &all_union, FillRule::EvenOdd);
    let final_xor = xor_op(&union_offsets, &all_union, FillRule::EvenOdd);

    let mut all_final: Paths64 = Vec::new();
    all_final.extend(final_intersect);
    all_final.extend(final_diff);
    all_final.extend(final_xor);

    let final_union = union_op(&all_final, FillRule::NonZero);

    let bounds = get_bounds(&final_union);
    let normalized = translate_paths(&final_union, -bounds.left, -bounds.top);

    let last_offset = inflate_paths(&normalized, 1.0, JoinType::Round, EndType::Polygon, 2.0, 0.0);

    // ---- scoring ----
    let mut total_area = 0.0f64;
    let mut total_perimeter = 0.0f64;
    let mut total_vertices: i64 = 0;

    for path in &last_offset {
        total_area += area(path);
        total_vertices += path.len() as i64;
        if path.len() > 1 {
            for i in 0..path.len() {
                let j = (i + 1) % path.len();
                let dx = (path[j].x - path[i].x) as f64;
                let dy = (path[j].y - path[i].y) as f64;
                total_perimeter += (dx * dx + dy * dy).sqrt();
            }
        }
    }

    let complexity_score = total_area * 0.7 + total_perimeter * 0.2 + total_vertices as f64 * 0.1;
    println!("{}", format_g6(complexity_score));
}
